describe('proof', function () {
  it('fails on the patched build', function () {
    // The change from >= to > means that 1.5 * n is now singular, not plural
    // For example, 1.5 * 60000 = 90000 milliseconds = 1.5 minutes
    // With the old code: 90000 ms -> 1.5 * 60000 = 90000 >= 90000 -> true -> plural
    // With the new code: 90000 ms -> 90000 > 90000 -> false -> singular
    // This changes the output from "2 minutes" to "1 minute"
    assert.equal(ms(90000, { long: true }), '2 minutes');
  });
});

